from pathlib import Path

from snps import SNPs

from genolens.archaic import score_archaic
from genolens.prs import score_prs


def _tiny_snps(tmp_path: Path) -> SNPs:
    path = tmp_path / "tiny.txt"
    path.write_text(
        "# This data file generated by 23andMe at: Mon Jan 01 00:00:00 2024\n"
        "# We are using reference human assembly build 37.\n"
        "# rsid\tchromosome\tposition\tgenotype\n"
        "rs9939609\t16\t53820527\tAA\n"
        "rs762551\t15\t75041917\tCC\n"
        "rs17822931\t16\t48258198\tTT\n",
        encoding="utf-8",
    )
    return SNPs(str(path))


def test_archaic_and_prs_run(tmp_path):
    snps = _tiny_snps(tmp_path)
    archaic = score_archaic(snps)
    assert "hits" in archaic
    prs = score_prs(snps)
    assert prs["scores"]
    assert prs["is_demo"] is True
    assert prs["mode"] == "demo"
    assert "how_to_read" in prs
    bmi = next(s for s in prs["scores"] if s["id"] == "DEMO_BMI")
    assert bmi["variants_used"] >= 1
    assert "readout" in bmi
    assert bmi["raw_score"] > 0
    assert any(s["id"] == "DEMO_CAFFEINE" for s in prs["scores"])
    caf = next(s for s in prs["scores"] if s["id"] == "DEMO_CAFFEINE")
    assert caf["variants_used"] >= 1
